export const statuses={Complete:'เสร็จสิ้น',Pending:'เปิดรับ',Full:'เต็มแล้ว','In-Progress':'กำลังเดินทาง'};
export function today(now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
export function tripDate(r){
 if(/^\d{4}-\d{2}-\d{2}$/.test(r.pickupDate||''))return r.pickupDate;
 const m=/^(\d{2})\/(\d{2})\/(\d{4})/.exec(r.date||'');return m?`${m[3]}-${m[2]}-${m[1]}`:'';
}
export const amount=r=>Number.isFinite(Number(r.co2))&&Number(r.co2)>=0?Math.round(Number(r.co2)*100):0;
export function filterRows(rows,f={}){return rows.filter(r=>{const d=tripDate(r);return (!f.year||d.slice(0,4)===f.year)&&(!f.month||d.slice(5,7)===f.month)&&(!f.driver||String(r.userId)===f.driver)&&(!f.status||r.status===f.status);});}
export function daily(rows,end=today()){
 const days=Array.from({length:30},(_,i)=>{const d=new Date(end+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-29+i);return {date:d.toISOString().slice(0,10),cents:0};});
 const lookup=new Map(days.map(d=>[d.date,d]));for(const r of rows){const d=lookup.get(tripDate(r));if(d)d.cents+=amount(r);}return days;
}
export function drivers(rows){const m=new Map();for(const r of rows){const id=String(r.userId);if(!m.has(id))m.set(id,{id,name:r.userName||r.driver||'ไม่ระบุ',trips:0,cents:0});const d=m.get(id);d.trips++;d.cents+=amount(r);}return [...m.values()].sort((a,b)=>b.cents-a.cents);}
export function exportRows(rows){return [['รหัสเที่ยว','วันที่รับ','แหล่งวันที่','วันที่สร้าง','รหัสผู้อาสา','ผู้อาสา','กะ','จุดรับ','ละติจูดรับ','ลองจิจูดรับ','จุดส่ง','ละติจูดส่ง','ลองจิจูดส่ง','สถานะ','ที่นั่งทั้งหมด','ผู้ร่วมเดินทาง (คน)','ชื่อผู้ร่วมเดินทาง','ระยะทาง (กม.)','CO2 (kg)'],...rows.map(r=>[String(r.id),tripDate(r),r.pickupDate?'วันที่รับ':'วันที่สร้าง (ข้อมูลเดิม)',r.date||'',String(r.userId),r.userName||r.driver||'',r.shift==='morning'?'กะเช้า':'กะเย็น',r.pickup?.name||'',r.pickup?.lat??'',r.pickup?.lng??'',r.dest?.name||'',r.dest?.lat??'',r.dest?.lng??'',statuses[r.status]||r.status,r.maxSeats??0,r.passengers?.length||0,(r.passengers||[]).map(p=>p.name).join(', '),Number(r.distance)||0,amount(r)/100])];}
export function csv(rows){return '\ufeff'+rows.map(row=>row.map(v=>'"'+String(typeof v==='string'&&/^[\s]*[=+@-]/.test(v)?"'"+v:v).replaceAll('"','""')+'"').join(',')).join('\r\n');}
// Minimal OOXML workbook in a standards-compliant, uncompressed ZIP; no CDN dependency.
const xml=s=>String(s).replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function zip(files){const encoder=new TextEncoder(),chunks=[],central=[];let offset=0;const u16=(a,n)=>{a.push(n&255,(n>>>8)&255);};const u32=(a,n)=>{u16(a,n);u16(a,n>>>16);};for(const [name,text] of files){const data=encoder.encode(text),path=encoder.encode(name);let crc=0xffffffff;for(const b of data){crc^=b;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}crc=(crc^0xffffffff)>>>0;const h=[];u32(h,0x04034b50);[20,0,0,0,33].forEach(x=>u16(h,x));[crc,data.length,data.length].forEach(x=>u32(h,x));u16(h,path.length);u16(h,0);chunks.push(new Uint8Array(h),path,data);const c=[];u32(c,0x02014b50);[20,20,0,0,0,33].forEach(x=>u16(c,x));[crc,data.length,data.length].forEach(x=>u32(c,x));[path.length,0,0,0,0].forEach(x=>u16(c,x));u32(c,0);u32(c,offset);central.push(new Uint8Array(c),path);offset+=h.length+path.length+data.length;}const size=central.reduce((n,b)=>n+b.length,0),end=[];u32(end,0x06054b50);[0,0,files.length,files.length].forEach(x=>u16(end,x));u32(end,size);u32(end,offset);u16(end,0);const all=[...chunks,...central,new Uint8Array(end)],out=new Uint8Array(offset+size+end.length);let pos=0;for(const b of all){out.set(b,pos);pos+=b.length;}return out;}
export function xlsx(rows){const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';const sheet=`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="${ns}"><sheetData>${rows.map((row,i)=>`<row r="${i+1}">${row.map(v=>typeof v==='number'&&Number.isFinite(v)?`<c><v>${v}</v></c>`:`<c t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')}</row>`).join('')}</sheetData></worksheet>`;return zip([
 ['[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'],
 ['_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],
 ['xl/workbook.xml',`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="ข้อมูลการเดินทาง" sheetId="1" r:id="rId1"/></sheets></workbook>`],
 ['xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'],['xl/worksheets/sheet1.xml',sheet]]);}
